"""Shared browser shell for the F1 ecosystem; no external browser dependencies."""
import re
from .web import HOME_HTML


def ecosystem_page(mode: str) -> str:
    css = re.search(r"<style>([\s\S]*?)</style>", HOME_HTML).group(1)
    html = TEMPLATE.replace("__CSS__", css).replace("__MODE__", mode)
    return html.replace('<a href="/telemetry/">Telemetry</a>', '<a href="/library/">Session library</a><a href="/race-lab/">Race Lab</a><a href="/telemetry/">Telemetry</a>', 1)


TEMPLATE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>F1 Intelligence Lab · Ecosystem</title><style>__CSS__
.eco{width:min(1240px,calc(100% - 48px));margin:auto}.eco-nav{display:flex;gap:22px;flex-wrap:wrap;align-items:center;border-bottom:1px solid var(--line);padding:18px 0}.eco-nav>a{font:11px var(--mono);text-decoration:none;min-height:36px;display:flex;align-items:center;color:var(--muted)}.eco-nav>a:first-child{font:900 italic 18px var(--display);color:#fff;margin-right:auto}.eco-nav a.active{color:#fff;box-shadow:0 3px var(--red)}.eco-head{padding:38px 0 24px;border-bottom:1px solid var(--line);margin-bottom:24px}.eco-head h1{font:950 italic clamp(36px,5vw,66px)/1 var(--display);letter-spacing:-.045em;margin:15px 0;text-transform:uppercase}.eco-head p{max-width:730px;color:var(--muted);font-size:14px;margin:0}.eco h2{font:750 13px var(--mono);text-transform:uppercase;letter-spacing:.04em}.eco .box{padding:24px;border:1px solid var(--line);background:var(--panel);border-radius:3px 18px 3px 3px;min-width:0}.eco .boxes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:22px 0}.eco .boxes.two{grid-template-columns:repeat(2,minmax(0,1fr))}.eco .metricline{display:flex;gap:30px;flex-wrap:wrap;padding:18px 0;border-bottom:1px solid var(--line);font:11px var(--mono);color:var(--muted)}.metricline b{font-size:24px;color:#fff;margin-right:8px}.eco label{display:block;font:10px var(--mono);text-transform:uppercase;color:var(--muted);margin:0 0 8px}.eco input,.eco select{width:100%;padding:12px;background:#111116;color:white;border:1px solid #44444e;border-radius:3px;font:13px var(--mono);min-height:44px}.eco button,.eco .go{display:inline-flex;justify-content:center;align-items:center;min-height:44px;background:#d91f2a;border:1px solid #d91f2a;border-radius:3px;color:white;padding:10px 18px;text-decoration:none;font:700 12px var(--display);cursor:pointer}.eco button:hover,.eco .go:hover{background:#f33b40}.eco button:disabled{opacity:.5;cursor:wait}.eco .quiet{background:#292932;border-color:#4b4b58}.eco .controls{display:flex;align-items:end;gap:16px;flex-wrap:wrap;margin:22px 0}.eco .controls>div{flex:1;min-width:180px}.eco .controls .short{flex:0 1 100px;min-width:90px}.eco .cardtitle{font:900 italic 27px var(--display);text-transform:uppercase;margin:15px 0}.eco .desc{font-size:13px;color:var(--muted);line-height:1.8}.eco .chip{font:10px var(--mono);color:#ff999d;border-left:3px solid var(--red);padding-left:9px}.eco .box .go{margin-top:15px}.eco .muted{font-size:12px;color:var(--muted);line-height:1.7}.eco .alert{padding:14px 18px;border-left:3px solid #737382;background:#202028;font-size:12px;margin:20px 0;color:#c7c7d1}.eco .err{color:#ff9da2;white-space:pre-wrap;overflow-wrap:anywhere}.eco .hidden{display:none!important}.eco table{width:100%;border-collapse:collapse;font-size:13px}.eco th{text-align:left;font:10px var(--mono);color:var(--muted);text-transform:uppercase}.eco td,.eco th{padding:16px 13px;border-bottom:1px solid var(--line);white-space:nowrap}.eco td:first-child{font-weight:800}.eco .tablewrap{overflow-x:auto}.eco progress{width:100%;height:10px;accent-color:var(--red)}.eco .replay-driver:nth-child(even) progress{accent-color:#64d8ff}.eco .readouts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:22px 0}.eco .readouts strong{font:800 24px var(--mono);display:block}.eco .readouts small{font:10px var(--mono);color:var(--muted)}.eco .clock{font:800 36px var(--mono);letter-spacing:-.05em}.eco .status{font:900 italic 32px var(--display);text-transform:uppercase}.eco .status.supported{color:#b8f28b}.eco .status.contradicted{color:#ff747b}.eco .evidence{font-size:12px;overflow-wrap:anywhere}.eco .evidence a{color:#ffb1b4}.eco .decision{border-top:3px solid var(--red)}.eco details{margin:16px 0}.eco summary{cursor:pointer;font-size:12px}.eco footer{margin-top:45px;border-top:1px solid var(--line);padding:24px 0;font-size:11px;color:var(--muted)}.eco .project-card{display:flex;flex-direction:column}.eco .project-card .desc{flex:1}.eco #scrub{padding:0;accent-color:var(--red)}.eco pre{white-space:pre-wrap;overflow-wrap:anywhere}.eco .coverage{font:10px var(--mono);color:#b8f28b;min-height:36px}.eco .empty{padding:30px;color:var(--muted)}@media(max-width:800px){.eco{width:calc(100% - 32px)}.eco .boxes,.eco .boxes.two{grid-template-columns:1fr}.eco-nav{gap:14px}.eco-nav>a:first-child{flex-basis:100%}.eco-nav>a{font-size:10px}.eco .readouts strong{font-size:22px}.eco .box{padding:20px}.eco-head{padding-top:28px}.eco .metricline{gap:18px}.eco .controls>div{min-width:140px}}
</style></head><body><div class="eco"><nav class="eco-nav" aria-label="F1 ecosystem"><a href="/">F1 / ECOSYSTEM</a><a href="/telemetry/">Telemetry</a><a href="/stewardlens/">StewardLens</a><a href="/pitwall/">Pitwall Replay</a><a href="/scoutgrid/">ScoutGrid</a><a href="/claimcheck/">ClaimCheck</a><a href="/archive/">FIA Archive</a></nav><header class="eco-head"><div class="kicker" id="eyebrow">F1 INTELLIGENCE LAB</div><h1 id="heading">ONE PADDOCK.<br><span style="color:var(--red)">EVERY ANGLE.</span></h1><p id="description">Replay the laps. Compare the drivers. Inspect the decisions. A connected collection of Formula 1 research tools, built around shared evidence.</p></header><main>
<div id="error" class="err" role="alert"></div>
<section id="hub" class="hidden"><div class="metricline" id="counts"></div><div class="controls"><div><label for="search">Find a tool</label><input id="search" type="search" placeholder="Replay, telemetry, penalties…"></div><div class="short"><label for="category">Category</label><select id="category"><option>All</option><option>Performance</option><option>Race control</option><option>Evidence</option></select></div></div><div class="boxes" id="projectcards"></div><div class="alert">All tools share the same local catalogue. The bundled real session is Monza 2024 qualifying; the synthetic session is separately labelled. These are functioning research MVPs with deterministic analysis, not a live race platform.</div></section>
<section id="sessionTools" class="hidden"><div class="controls"><div><label for="session">Session catalogue</label><select id="session"></select></div><div id="sortWrap" class="hidden"><label for="sort">Sort laps by</label><select id="sort"><option value="lap_time">Lap time · quickest first</option><option value="top_speed">Sampled top speed · highest first</option><option value="driver">Driver code</option></select></div><a id="telemetryLink" class="go quiet" href="/telemetry/">Open in Telemetry ↗</a></div><p class="muted" id="sessionNote"></p></section>
<section id="pitwall" class="hidden"><div class="box"><div class="controls"><button id="play" disabled>Play replay</button><button id="restart" class="quiet" disabled>Restart</button><div class="short"><label for="rate">Playback speed</label><select id="rate"><option value=".5">0.5×</option><option selected value="1">1×</option><option value="2">2×</option><option value="4">4×</option></select></div><div class="clock" id="clock">0.000 s</div></div><label for="scrub">Lap-relative clock · drag to inspect a moment</label><input type="range" id="scrub" min="0" max="1" step="0.01" value="0" disabled><p class="muted" id="replayNote"></p></div><div class="boxes two" id="replayDrivers"></div></section>
<section id="scoutgrid" class="hidden"><div class="box tablewrap"><table><thead><tr><th>Driver</th><th>Lap</th><th>Time (s)</th><th>Gap (s)</th><th>Top speed (km/h)</th><th>Min speed (km/h)</th><th>Samples</th><th>Compound</th></tr></thead><tbody id="scoutRows"></tbody></table></div><div class="alert" id="scoutNote"></div><button class="quiet" id="exportScout">Download session report</button></section>
<section id="claimcheck" class="hidden"><div class="box"><h2>Check a supported numerical claim</h2><p class="muted">Choose a source record and enter the number you want to verify. This checks recorded values; it does not judge opinions or infer why an incident happened.</p><form id="claimForm"><div class="controls"><div><label for="kind">Claim type</label><select id="kind"><option value="lap_time">Lap time in seconds</option><option value="lap_delta">Lap time A minus B in seconds</option><option value="penalty_seconds">Official time penalty in seconds</option></select></div><div><label for="value">Claimed number (seconds)</label><input id="value" type="number" step="any" required value="79.327" min="-100000" max="100000"></div></div><div class="controls" id="lapFields"><div><label for="claimSession">Session</label><select id="claimSession"></select></div><div><label for="lapA">Lap A</label><select id="lapA"></select></div><div id="lapBWrap" class="hidden"><label for="lapB">Lap B</label><select id="lapB"></select></div></div><div class="controls hidden" id="decisionFields"><div><label for="decision">Official decision</label><select id="decision"></select></div></div><button id="checkButton" type="submit">Check against evidence →</button></form></div><div class="box hidden" style="margin-top:22px" id="claimResult" aria-live="polite"></div><button class="quiet hidden" style="margin-top:16px" id="exportClaim">Download evidence report</button></section>
<section id="archive" class="hidden"><div class="controls"><div><label for="archiveSearch">Search the cached FIA archive</label><input type="search" id="archiveSearch" placeholder="Driver, event, decision or article"></div></div><div class="boxes two" id="decisions"></div><p class="muted">Official source records are independent of StewardLens's fictional demonstration cases.</p></section>
</main><footer>Independent educational project. Not affiliated with Formula 1, the FIA, teams or drivers. Recorded data is not live timing. <a href="/docs">Ecosystem API ↗</a></footer></div>
<script>
const mode='__MODE__', $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{try{const u=new URL(v,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
async function api(url,options){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Please check the selected inputs.');return d}
const show=(id,on=true)=>$(id).classList.toggle('hidden',!on);
let catalogue,decisions=[],scoutData,claimResult,replayData,playing=false,current=0,last=0,frame=0,loadVersion=0,claimLoadVersion=0;
const titles={pitwall:['03 / PLAYBACK WORKSTATION','PITWALL REPLAY','Scrub through recorded laps using one lap-relative clock. Inspect speed, throttle and gear at each recorded sample.'],scoutgrid:['04 / DRIVER EXPLORER','SCOUTGRID','Compare the available laps within a session. Explore timing and sampled speed without turning one lap into a verdict on driver talent.'],claimcheck:['05 / EVIDENCE WORKSTATION','CLAIMCHECK','Put a number to the test. Check lap times, signed time differences and official time penalties against the source records.'],archive:['06 / SOURCE LIBRARY','FIA ARCHIVE','Inspect the official decisions used by the ecosystem, with original source documents and integrity references.']};
if(titles[mode]){$('eyebrow').textContent=titles[mode][0];$('heading').textContent=titles[mode][1];$('description').textContent=titles[mode][2];document.title=titles[mode][1]+' · F1 Ecosystem'}
document.querySelectorAll('.eco-nav a').forEach(a=>{if(a.pathname===location.pathname)a.classList.add('active')});show(mode);
function download(name,data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function cards(){const q=$('search').value.toLowerCase(),cat=$('category').value;const p=catalogue.projects.filter(p=>(cat==='All'||p.category===cat)&&(p.name+' '+p.description).toLowerCase().includes(q));$('projectcards').innerHTML=p.map(p=>`<article class="box project-card"><span class="chip">${esc(p.category)} / AVAILABLE</span><h2 class="cardtitle">${esc(p.name)}</h2><p class="desc">${esc(p.description)}</p><a class="go" href="${esc(p.path)}">Open workstation ↗</a></article>`).join('')||'<p class="empty">No tools match. Clear the search or choose another category.</p>'}
function archiveCards(){const q=$('archiveSearch').value.toLowerCase(),items=decisions.filter(d=>(d.driver_name+' '+d.event+' '+d.decision+' '+d.infringement).toLowerCase().includes(q));$('decisions').innerHTML=items.map(d=>`<article class="box decision"><span class="chip">${esc(d.season)} / DOC ${esc(d.document_number)} / CAR ${esc(d.driver_number)}</span><h2 class="cardtitle">${esc(d.driver_name)}</h2><p>${esc(d.event)} · ${esc(d.session)}</p><p class="desc">${esc(d.fact)}</p><strong>${esc(d.decision)}</strong><details><summary>Article, reasoning and document integrity</summary><p class="muted">${esc(d.infringement)}</p><p class="muted">${esc(d.reason)}</p><p class="evidence">SHA-256: ${esc(d.sha256)}</p><p class="muted">Retrieved ${esc(d.retrieved_at)}</p></details><a class="go" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(d.source_document_url))}">Original FIA document ↗</a></article>`).join('')||'<p class="empty">No documents match this search.</p>'}
function sessionOptions(){return catalogue.sessions.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}${s.source_type==='synthetic'?' · SYNTHETIC':''}</option>`).join('')}
function scoutRows(){if(!scoutData)return;const key=$('sort').value,rows=[...scoutData.rows].sort((a,b)=>key==='driver'?a.driver.localeCompare(b.driver):key==='top_speed'?(b[key]??-Infinity)-(a[key]??-Infinity):a[key]-b[key]);$('scoutRows').innerHTML=rows.map(r=>`<tr><td>${esc(r.driver)}</td><td>${r.lap_number}</td><td>${r.lap_time.toFixed(3)}</td><td>+${r.gap_to_fastest.toFixed(3)}</td><td>${r.top_speed??'—'}</td><td>${r.minimum_speed??'—'}</td><td>${r.samples}</td><td>${esc(r.compound)}</td></tr>`).join('')||'<tr><td colspan="8">No laps in this session.</td></tr>'}
function stop(){playing=false;cancelAnimationFrame(frame);$('play').textContent='Play replay'}
function renderReplay(){if(!replayData)return;$('clock').textContent=current.toFixed(3)+' s';$('scrub').value=current;replayData.laps.forEach((lap,i)=>{const sorted=lap.samples;let lo=0,hi=sorted.length-1,index=-1;while(lo<=hi){const mid=(lo+hi)>>1;if(sorted[mid].time<=current){index=mid;lo=mid+1}else hi=mid-1}const finished=current>=lap.lap_time;const inRange=index>=0&&current<=sorted[sorted.length-1].time&&!finished;const s=inRange?sorted[index]:null;$('speed'+i).textContent=s?s.speed.toFixed(0):'—';$('throttle'+i).textContent=s?s.throttle.toFixed(0):'—';$('gear'+i).textContent=s?s.gear:'—';$('progress'+i).value=Math.min(current/lap.lap_time*100,100);$('coverage'+i).textContent=finished?'LAP COMPLETE':s?`Sample ${s.time.toFixed(3)} s · brake ${s.brake?'ON':'OFF'}`:'No telemetry coverage at this timestamp';})}
function tick(now){if(!playing)return;if(last)current=Math.min(replayData.duration,current+(now-last)/1000*Number($('rate').value));last=now;renderReplay();if(current>=replayData.duration){stop();return}frame=requestAnimationFrame(tick)}
async function loadSession(){const version=++loadVersion;stop();replayData=null;scoutData=null;$('play').disabled=true;$('restart').disabled=true;$('scrub').disabled=true;$('exportScout').disabled=true;$('replayDrivers').innerHTML='';$('scoutRows').innerHTML='';$('error').textContent='';const id=$('session').value;const s=catalogue.sessions.find(s=>s.id===id);$('sessionNote').textContent=(s.source_type==='synthetic'?'SYNTHETIC DEMO. ':'RECORDED SESSION. ')+(s.notes||'');$('telemetryLink').href='/telemetry/?session='+encodeURIComponent(id);try{const data=await api('/api/ecosystem/'+(mode==='pitwall'?'replay':'scout')+'?session_id='+encodeURIComponent(id));if(version!==loadVersion)return;if(mode==='scoutgrid'){scoutData=data;scoutRows();$('scoutNote').textContent=data.limitation;$('exportScout').disabled=false}else{replayData=data;replayData.laps.forEach(l=>l.samples.sort((a,b)=>a.time-b.time));current=0;$('scrub').max=data.duration;$('replayNote').textContent=data.limitation;$('replayDrivers').innerHTML=data.laps.map((lap,i)=>`<article class="box replay-driver"><span class="chip">LAP ${lap.lap_number} / ${esc(lap.compound)}</span><h2 class="cardtitle">${esc(lap.driver)} <span class="muted">${lap.lap_time.toFixed(3)} s</span></h2><label for="progress${i}">Elapsed lap-time progress</label><progress id="progress${i}" max="100" value="0"></progress><div class="readouts"><div><strong id="speed${i}">—</strong><small>KM/H</small></div><div><strong id="throttle${i}">—</strong><small>THROTTLE %</small></div><div><strong id="gear${i}">—</strong><small>GEAR</small></div></div><p class="coverage" id="coverage${i}"></p></article>`).join('');$('play').disabled=!data.laps.length;$('restart').disabled=!data.laps.length;$('scrub').disabled=!data.laps.length;renderReplay()}}catch(e){if(version===loadVersion)$('error').textContent=e.message}}
function clearClaim(){claimResult=null;show('claimResult',false);show('exportClaim',false)}
async function claimLaps(){const version=++claimLoadVersion;clearClaim();$('checkButton').disabled=true;try{const laps=await api('/telemetry/laps?session_id='+encodeURIComponent($('claimSession').value));if(version!==claimLoadVersion)return;const opts=laps.map(l=>`<option value="${esc(l.id)}">${esc(l.driver)} · lap ${l.lap_number}</option>`).join('');$('lapA').innerHTML=opts;$('lapB').innerHTML=opts;if(laps[1])$('lapB').value=laps[1].id;$('checkButton').disabled=!laps.length}catch(e){if(version===claimLoadVersion)$('error').textContent=e.message}}
$('kind').onchange=()=>{clearClaim();const penalty=$('kind').value==='penalty_seconds';show('decisionFields',penalty);show('lapFields',!penalty);show('lapBWrap',$('kind').value==='lap_delta')};
$('claimForm').oninput=clearClaim;
$('claimForm').onsubmit=async event=>{event.preventDefault();clearClaim();$('error').textContent='';$('checkButton').disabled=true;const payload={kind:$('kind').value,value:Number($('value').value),session_id:$('claimSession').value,lap_a_id:$('lapA').value,lap_b_id:$('lapB').value,decision_id:$('decision').value};const signature=JSON.stringify(payload);try{const result=await api('/api/ecosystem/check',{method:'POST',headers:{'Content-Type':'application/json'},body:signature});const now={kind:$('kind').value,value:Number($('value').value),session_id:$('claimSession').value,lap_a_id:$('lapA').value,lap_b_id:$('lapB').value,decision_id:$('decision').value};if(JSON.stringify(now)!==signature)return;claimResult=result;$('claimResult').innerHTML=`<div class="status ${esc(result.status)}">${esc(result.status.replaceAll('_',' '))}</div>`+(result.evidence?`<p>Claimed: <strong>${result.claimed} s</strong> · Recorded: <strong>${result.observed} s</strong></p><p class="muted">Tolerance: ${result.tolerance_seconds} seconds. Source type: ${esc(result.evidence.source_type)}.</p><p class="evidence"><a href="${esc(safeUrl(result.evidence.url))}" target="_blank" rel="noopener noreferrer">${esc(result.evidence.label)} ↗</a></p><p class="muted">${esc(result.scope)}</p>`:`<p>${esc(result.reason)}</p>`);show('claimResult');show('exportClaim')}catch(e){$('error').textContent=e.message}finally{$('checkButton').disabled=false}};
$('search').oninput=cards;$('category').onchange=cards;$('archiveSearch').oninput=archiveCards;$('session').onchange=loadSession;$('sort').onchange=scoutRows;$('claimSession').onchange=claimLaps;$('play').onclick=()=>{if(playing){stop();return}if(!replayData)return;if(current>=replayData.duration)current=0;playing=true;last=0;$('play').textContent='Pause replay';frame=requestAnimationFrame(tick)};$('restart').onclick=()=>{stop();current=0;renderReplay()};$('scrub').oninput=()=>{stop();current=Number($('scrub').value);renderReplay()};$('exportScout').onclick=()=>{if(scoutData)download('scoutgrid-session.json',scoutData)};$('exportClaim').onclick=()=>{if(claimResult)download('claimcheck-evidence.json',claimResult)};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
async function init(){catalogue=await api('/api/ecosystem/catalog');const preferred=new URLSearchParams(location.search).get('session');const defaultId=catalogue.sessions.find(s=>s.id===preferred)?.id||catalogue.sessions.find(s=>s.source_type!=='synthetic')?.id||catalogue.sessions[0]?.id;if(mode==='hub'){$('counts').innerHTML=`<span><b>${catalogue.projects.length}</b> tools</span><span><b>${catalogue.recorded_sessions}</b> recorded sessions</span><span><b>${catalogue.synthetic_sessions}</b> synthetic demos</span><span><b>${catalogue.official_documents}</b> official documents</span>`;cards()}if(['pitwall','scoutgrid'].includes(mode)){show('sessionTools');show('sortWrap',mode==='scoutgrid');$('session').innerHTML=sessionOptions();$('session').value=defaultId;await loadSession()}if(['archive','claimcheck'].includes(mode)){decisions=await api('/stewardlens/fia-decisions');if(mode==='archive')archiveCards();else{$('decision').innerHTML=decisions.map(d=>`<option value="${esc(d.id)}">Doc ${d.document_number} · ${esc(d.driver_name)} · ${d.season}</option>`).join('');$('claimSession').innerHTML=sessionOptions();$('claimSession').value=defaultId;await claimLaps()}}}
init().catch(e=>{$('error').textContent='Could not load the catalogue. '+e.message+' Reload to retry.'});
</script></body></html>'''
